def chromium_path():
    override=os.getenv('PA_TEST_CHROMIUM')
    if override:return override
    for name in ('chromium','chromium-browser','google-chrome','google-chrome-stable'):
        path=shutil.which(name)
        if path:return path
    return None

def install_storage(page,name,initial=None):
    initial=initial or {};script=f"Object.defineProperty(window,{json.dumps(name)},{{configurable:true,value:{{d:{json.dumps(initial,ensure_ascii=False)},setItem(k,v){{this.d[k]=String(v)}},getItem(k){{return Object.prototype.hasOwnProperty.call(this.d,k)?this.d[k]:null}},removeItem(k){{delete this.d[k]}},clear(){{this.d={{}}}}}}}});";page.evaluate(script)

def load_user(page,storage=None):
    page.set_content(INDEX);install_storage(page,'localStorage',storage);install_storage(page,'sessionStorage',{});page.add_style_tag(content=CSS);page.add_script_tag(content=BACKEND_STUB);page.add_script_tag(content=APP);expect(page.locator('.mode')).to_have_count(3)

def load_admin(page,storage=None):
    page.set_content(ADMIN);install_storage(page,'sessionStorage',storage);page.add_style_tag(content=CSS);page.add_script_tag(content=BACKEND_STUB);page.add_script_tag(content=ADMIN_JS)

def load_account(page):
    page.set_content(ACCOUNT);page.add_style_tag(content=CSS);page.add_script_tag(content=BACKEND_STUB);page.add_script_tag(content=AUTH_JS)

