        for secret in ('qwen','ollama','provider_id','model_id'):assert secret not in body,secret
        # Structured preset is independent from Smart mode.
        page.locator('.starter-card[data-preset="analyze"]').click();page.get_by_role('button',name='Умно',exact=True).click();page.locator('#input').fill('ок');page.locator('#send').click();expect(page.locator('.msg.assistant')).to_have_count(1);assert 'Хорошо' in page.locator('.msg.assistant').last.inner_text();assert page.evaluate('window.__backend.lastMode')=='smart';assert page.evaluate('window.__backend.lastPreset')=='analyze'
        page.locator('#input').fill('PAR_MARKDOWN');page.locator('#send').click();expect(page.locator('.code-block')).to_have_count(1)
