        page.locator('#filesEntry').click();expect(page.locator('[data-settings-panel="files"]')).to_have_class(re.compile('active'));expect(page.locator('#artifactList .artifact-row')).to_have_count(1);page.locator('#artifactFormat').select_option('pdf');page.locator('#artifactName').fill('report.pdf');page.locator('#artifactContent').fill('Тестовый PDF');page.locator('#createArtifact').click();expect(page.locator('#artifactList .artifact-row')).to_have_count(2);page.locator('#closeSettings').click()
        # Code UI journey: open sandbox, execute, poll result.
        page.locator('#codeEntry').click();expect(page.locator('[data-settings-panel="code"]')).to_have_class(re.compile('active'));expect(page.locator('#codeRunState')).to_contain_text('Sandbox');page.locator('#codeLanguage').select_option('python');page.locator('#codeEditor').fill('print("CODE_OK")');page.locator('#runCode').click();expect(page.locator('#codeStdout')).to_contain_text('CODE_OK',timeout=5000);expect(page.locator('#codeRunState')).to_contain_text('COMPLETED');page.locator('#closeSettings').click()
        page.locator('#newChat').click();page.locator('#input').fill('Второй отдельный диалог');page.locator('#send').click();page.locator('#chatMenuButton').click();page.locator('#chatMenu [data-action="rename"]').click();page.locator('#actionInput').fill('Рабочий чат');page.locator('#actionConfirm').click();expect(page.locator('#conversationTitle')).to_have_text('Рабочий чат');page.locator('#chatSearch').fill('Рабочий');expect(page.locator('.conversation-item')).to_have_count(1);page.locator('#chatSearch').fill('')
