        mobile=browser.new_page(viewport={'width':390,'height':844});load_user(mobile);mobile.locator('#openSidebar').click();mobile.wait_for_timeout(260);expect(mobile.locator('#sidebar')).to_be_visible();assert mobile.locator('#accountEntry').count()==1 and mobile.locator('a[href="/admin"]').count()>=1
        account=browser.new_page(viewport={'width':1100,'height':800});load_account(account);expect(account.locator('#billingAccount')).to_be_visible();expect(account.locator('#currentPlan')).to_have_text('Лайт');prices=account.locator('.plan-price').all_inner_texts();assert 'Бесплатно' in prices and '500 ₽/мес' in prices and '1000 ₽/мес' in prices;assert 'Локально' in account.locator('#usageSummary').inner_text();account.locator('#showTokens').check();assert account.evaluate('window.__backend.showTokens') is True
        admin=browser.new_page(viewport={'width':1280,'height':900});load_admin(admin);admin.locator('#token').fill('browser-admin-token-123');admin.locator('#loginBtn').click();admin.locator('#admin').wait_for(state='visible')
